<!-- This file is generated by AI. -->
<!--
  资源浏览器: 列出 `game` 下的全部资源, 单击选中并在右侧预览, 双击才开选项卡。

  坐在通用 `FileTree` 上, 只补资源专属的部分: 根目录、可预览资源的地址、以及"列表 | 预览"
  的两栏布局。

  两条容易搞错的点:

  * **`assetUrl` 必须带 `game/` 前缀**。预览服务器把**项目根**挂成站点根, 因此逻辑路径是
    `game/xxx/yyy.png`; 而 `assetBase` 已经到 `.../game/{hash}/s/` 这一层。少了 `game/` 拼
    出来的地址必然 404。
  * **单击 ≠ 打开**。资源目录里挑素材是高频操作, 每次单击都开一个选项卡会把选项卡栏塞满;
    因此单击只选中 + 右侧预览, 双击才开。

  ⚠️ 不带 `<style>` 块: 类名全部来自全局 `styles.css`。
-->
<script lang="ts">
  import { revealItemInDir } from '@tauri-apps/plugin-opener';

  import { gitStage } from '../commands/git';
  import { requestAlert, requestConfirm } from '../confirm';
  import {
    copyEntryToDirectory,
    copyRelativePathToClipboard,
    createFile,
    createFolder,
    deletePath,
    ensureExtension,
    importFilesToDir,
    renamePath,
    validateName,
  } from '../fileops';
  import { buildDiagnosticIndex } from '../diagnostics/model';
  import { absToRel, buildGitLetterIndex, normalizeRelPath, stageMenuItem } from '../git/util';
  import { refreshGitStatus } from '../git/status';
  import { assetUrlFor } from '../lib/assetUrl';
  import { fs } from '../lib/fs';
  import { joinPath } from '../lib/paths';
  import { previewClient } from '../preview/client';
  import { configPathOf, openProjectConfig, openResourceFile } from '../project';
  import { activeTabOf } from '../state/selectors';
  import { appStore } from '../state/store.svelte';
  import type { ResourceKind } from '../tabs/model';
  import ContextMenu, { type ContextMenuItem } from './ContextMenu.svelte';
  import FileBadges from './FileBadges.svelte';
  import FileTree, { type FileNode, type FileTreeRevealRequest, type FileTreeViewStateCache } from './FileTree.svelte';
  import NameInputDialog from './NameInputDialog.svelte';

  let {
    viewStateCache,
    viewStateKey,
    revealRequest = null,
    onRevealComplete,
  }: {
    viewStateCache?: FileTreeViewStateCache;
    viewStateKey?: string;
    revealRequest?: FileTreeRevealRequest | null;
    onRevealComplete?: (id: number) => void;
  } = $props();

  const projectPath = $derived(appStore.projectPath);
  const gameRoot = $derived(projectPath ? joinPath(projectPath, 'game') : '');

  /** 预览站点的地址前缀 —— 媒体资源直接从这里取, 不走文件字节 (立绘可以很大)。 */
  let assetBase = $state<string | null>(null);

  let refreshKey = $state(0);
  let blankMenu = $state<{ x: number; y: number; dir: string } | null>(null);
  let itemMenu = $state<{ x: number; y: number; node: FileNode } | null>(null);
  let prompt = $state<{ mode: 'file' | 'folder' | 'rename'; dir: string; node?: FileNode } | null>(null);
  /** 右侧预览选中的文件 (单击设置, 再点一次取消) */
  let previewNode = $state<FileNode | null>(null);
  /**
   * 正在打开的资源路径。
   *
   * 打开是异步的, 而"活动选项卡"要等它落定才更新 —— 中间这段时间预览会闪一下, 这个字段
   * 就是用来抑制它的。
   */
  let openingPath = $state<string | null>(null);
  /**
   * 单击预览的延迟句柄。
   *
   * 220ms 的延迟让"双击"不会被当成两次单击 (否则双击打开时预览会先闪一下再收起)。
   */
  let selectTimer: ReturnType<typeof setTimeout> | null = null;

  const activeTab = $derived(activeTabOf(appStore));
  const selectedPath = $derived(activeTab?.kind === 'resource' || activeTab?.kind === 'config' ? activeTab.path : null);

  // 站点地址在项目/引擎变化后重取
  $effect(() => {
    const path = projectPath;
    const enginePath = resolveEnginePath();
    if (!path) {
      assetBase = null;
      return;
    }
    let cancelled = false;
    void (async () => {
      const url = await previewClient.ensureSite(path, enginePath);
      if (!cancelled) assetBase = url;
    })();
    return () => {
      cancelled = true;
    };
  });

  function resolveEnginePath(): string | undefined {
    const path = appStore.projectPath;
    if (!path) return undefined;
    const key = path.replace(/\\/g, '/').toLowerCase();
    const binding = Object.entries(appStore.projectBindings).find(
      ([entryKey]) => entryKey.replace(/\\/g, '/').toLowerCase() === key
    )?.[1];
    return appStore.settings.engines.find((engine) => engine.id === binding?.engineId)?.path;
  }

  const assetUrl = (rel: string) => assetUrlFor(assetBase, rel);

  /** 资源页隐藏根下的 `scene/` (那是场景页的地盘)。 */
  const isSceneDirectory = (name: string) => name.toLowerCase() === 'scene';

  function refresh(): void {
    refreshKey += 1;
  }

  /**
   * 「添加资源」= **导入已有文件** (多选对话框 → 逐个拷入当前目录, 重名自动改名), 不是"新建一个
   * 空文件" —— 资源浏览的主要用法正是从别处把素材拷进来。复制完刷新目录。
   */
  async function addResources(dir: string): Promise<void> {
    try {
      const created = await importFilesToDir(dir);
      if (created.length > 0) refresh();
    } catch (error) {
      requestAlert('添加资源失败', String(error));
    }
  }

  /** 「复制相对路径」: 相对项目根, 实现在 `fileops.ts` (两个浏览器共用这一处口径)。 */
  async function copyRelativePath(path: string): Promise<void> {
    const project = projectPath;
    if (!project) return;
    await copyRelativePathToClipboard(project, path);
  }

  /** 文件种类 -> 资源选项卡的种类 (场景页的 `.txt` 在这里就是普通文本)。 */
  function resourceKindOf(node: FileNode): ResourceKind {
    if (node.kind === 'image' || node.kind === 'audio' || node.kind === 'video') return node.kind;
    return 'text';
  }

  /**
   * 打开资源。
   *
   * `game/config.txt` 要开成**配置卡**而不是普通资源卡: 它有专门的校验与界面, 开成资源卡会
   * 绕过那套逻辑, 同一个文件出现两种编辑体验。
   */
  async function openResource(node: FileNode): Promise<void> {
    if (selectTimer) {
      clearTimeout(selectTimer);
      selectTimer = null;
    }
    openingPath = node.path;
    try {
      const path = projectPath;
      if (
        path &&
        configPathOf(path).replace(/\\/g, '/').toLowerCase() === node.path.replace(/\\/g, '/').toLowerCase()
      ) {
        await openProjectConfig(path);
        return;
      }
      // 打开时把选中同步成这个资源 —— 它随即成为活动选项卡, 于是 `previewVisible` 变假,
      // 右侧预览让位给编辑器
      previewNode = node;
      await openResourceFile(node.path, resourceKindOf(node));
    } catch (error) {
      requestAlert('打开资源失败', `${node.name}\n\n${String(error)}`);
    } finally {
      openingPath = null;
    }
  }

  /**
   * 单击: 选中并在右侧预览 (不开选项卡)。
   *
   * 两条语义都要保住:
   *   * **再点一次同一项 = 取消选中** (用户想收起预览时的自然动作, 也对应资源管理器里
   *     "点空白取消选择"的习惯);
   *   * **延迟 220ms**: 双击打开时不该先闪一下预览。
   */
  function selectResource(node: FileNode): void {
    if (selectTimer) {
      clearTimeout(selectTimer);
      selectTimer = null;
    }
    if (previewNode?.path === node.path) {
      previewNode = null;
      return;
    }
    selectTimer = setTimeout(() => {
      previewNode = node;
      selectTimer = null;
    }, 220);
  }

  /** 目录变了: 撤销右侧预览。 */
  function clearPreview(): void {
    if (selectTimer) {
      clearTimeout(selectTimer);
      selectTimer = null;
    }
    previewNode = null;
  }

  // 组件销毁时别留下定时器
  $effect(() => () => {
    if (selectTimer) clearTimeout(selectTimer);
  });

  function droppedPaths(event: DragEvent): string[] {
    const direct = Array.from(event.dataTransfer?.files ?? [])
      .map((file) => (file as File & { path?: string }).path)
      .filter((path): path is string => Boolean(path));
    if (direct.length > 0) return direct;

    const fallback = event.dataTransfer?.getData('text/uri-list') ?? '';
    return fallback
      .split(/\r?\n/)
      .map((line) => line.trim())
      .filter((line) => line.startsWith('file://'))
      .map((line) => decodeURIComponent(line.replace(/^file:\/\//, '').replace(/^\\\?\\/, '')));
  }

  async function handleDropFiles(directory: string, event: DragEvent): Promise<void> {
    const paths = droppedPaths(event);
    if (paths.length === 0) return;
    try {
      for (const source of paths) await copyEntryToDirectory(source, directory);
      refresh();
    } catch (error) {
      requestAlert('导入失败', `${String(error)}\n\n目标目录：${directory}`);
    }
  }

  function askDelete(node: FileNode): void {
    requestConfirm({
      title: '移入回收站',
      description: `将「${node.name}」移入系统回收站（可恢复）。`,
      confirmLabel: '移入回收站',
      danger: true,
      action: () => {
        void (async () => {
          try {
            await deletePath(node.path);
            if (previewNode?.path === node.path) previewNode = null;
            refresh();
          } catch (error) {
            requestAlert('移入回收站失败', `${node.name}\n\n${String(error)}`);
          }
        })();
      },
    });
  }

  function askStage(node: FileNode): void {
    const path = projectPath;
    if (!path) return;
    void (async () => {
      try {
        await gitStage(path, [absToRel(path, node.path)]);
        await refreshGitStatus(path);
      } catch (error) {
        requestAlert('暂存失败', `${node.name}\n\n${String(error)}`);
      }
    })();
  }

  /*
   * 工具栏 ⋮ 与列表空白处共用同一份菜单, 都作用于当前目录: 添加资源 / 新建文件夹 /
   * 在文件管理器中打开 —— 三项一个都不能少。
   */
  function toolbarMenu(directory: string): ContextMenuItem[] {
    return [
      {
        key: 'add-resource',
        label: '添加资源',
        iconName: 'DocumentAdd',
        onClick: () => void addResources(directory),
      },
      {
        key: 'new-folder',
        label: '新建文件夹',
        iconName: 'FolderAdd',
        onClick: () => (prompt = { mode: 'folder', dir: directory }),
      },
      {
        key: 'reveal',
        label: '在文件管理器中打开',
        iconName: 'OpenFolder',
        onClick: () => void revealItemInDir(directory),
      },
    ];
  }

  const blankItems = $derived<ContextMenuItem[]>(blankMenu ? toolbarMenu(blankMenu.dir) : []);

  /*
   * 行徽标的数据源: **建一次表**, 每行只查一次。
   *
   * 让每行自己读 store 会变成"每行一个订阅 + 每行 O(M) 线性查找", 文件多时进列表与滚动都会卡
   * (见 `ui/FileBadges.svelte`)。这里两个 `$derived` 只在 gitStatus / diagnostics 真变化时各跑
   * 一次 O(M) 建表, 之后每行是 O(1) 查表。
   */
  const gitLetters = $derived(buildGitLetterIndex(appStore.gitStatus));
  const diagCounts = $derived(buildDiagnosticIndex(appStore.diagnostics));

  /**
   * 「暂存」这一项的状态 (见 `git/util.ts` 的 `stageMenuItem`)。
   *
   * 未跟踪的文件不给这一项、没有仓库时整组消失、已暂存且工作区干净时显示但禁用。
   */
  const stageState = $derived(
    itemMenu && projectPath
      ? stageMenuItem(appStore.gitStatus, projectPath, itemMenu.node.path)
      : { visible: false, disabled: true }
  );

  /*
   * 行菜单: 文件与目录同一套, 没有"目录另开一支"的分支 (空白菜单才走 `blankItems`)。
   * 「暂存」只在可见时插在最前, 与场景浏览保持一致; 未跟踪的文件不给它, 已暂存且工作区干净时
   * 显示但禁用 (判据见 `git/util.ts` 的 `stageMenuItem`)。
   */
  const itemItems = $derived<ContextMenuItem[]>(
    itemMenu
      ? [
          ...(!itemMenu.node.isDirectory && stageState.visible
            ? [
                {
                  key: 'stage',
                  label: '暂存',
                  iconName: 'Add' as const,
                  disabled: stageState.disabled,
                  title: stageState.disabled ? '此文件已暂存' : undefined,
                  onClick: () => askStage(itemMenu!.node),
                },
                { key: 'separator-stage', separator: true as const },
              ]
            : []),
          {
            key: 'copy-relative',
            label: '复制相对路径',
            iconName: 'Copy',
            onClick: () => void copyRelativePath(itemMenu!.node.path),
          },
          {
            key: 'reveal',
            label: '在文件管理器中打开',
            iconName: 'OpenFolder',
            onClick: () => void revealItemInDir(itemMenu!.node.path),
          },
          { key: 'separator-manage', separator: true },
          {
            key: 'rename',
            label: '重命名',
            iconName: 'Rename',
            onClick: () => (prompt = { mode: 'rename', dir: itemMenu!.node.path, node: itemMenu!.node }),
          },
          {
            key: 'delete',
            label: '移入回收站',
            iconName: 'Delete',
            danger: true,
            onClick: () => askDelete(itemMenu!.node),
          },
        ]
      : []
  );

  const promptTitle = $derived(
    prompt?.mode === 'rename' ? '重命名' : prompt?.mode === 'folder' ? '新建文件夹' : '添加资源'
  );
  const promptInitial = $derived(prompt?.mode === 'rename' && prompt.node ? prompt.node.name : '');

  function targetName(raw: string): string {
    return ensureExtension(raw, 'txt');
  }

  /**
   * 就地校验: 名称合法性 + 重名。
   *
   * 资源目录里重名比场景页更常见 (两张 `立绘.png` 放同一目录), 因此这里的检查是必要的而不是
   * 锦上添花。重命名只改大小写时不算冲突 (Windows 上那是同一个文件)。
   */
  async function validateTarget(raw: string): Promise<string | null> {
    const current = prompt;
    if (!current) return null;

    const formatError = validateName(raw);
    if (formatError) return formatError;

    const isRename = current.mode === 'rename' && current.node;
    const name = isRename || current.mode === 'folder' ? raw.trim() : targetName(raw);
    const directory = isRename ? current.node!.path.replace(/[\\/][^\\/]*$/, '') : current.dir;
    const target = `${directory.replace(/[\\/]+$/, '')}\\${name}`;

    if (isRename && target.replace(/\\/g, '/').toLowerCase() === current.node!.path.replace(/\\/g, '/').toLowerCase()) {
      return null;
    }
    const info = await fs.exists(target);
    return info.exists ? '这个名字已经被占用了' : null;
  }

  async function submitPrompt(name: string): Promise<string | null> {
    const current = prompt;
    if (!current) return null;
    const invalid = validateName(name);
    if (invalid) return invalid;

    try {
      if (current.mode === 'file') {
        const created = await createFile(current.dir, name, 'txt');
        refresh();
        // 新建后直接打开, 与场景页一致: 建文件的目的就是用它
        await openResourceFile(created, 'text');
      } else if (current.mode === 'folder') {
        await createFolder(current.dir, name);
        refresh();
      } else if (current.node) {
        const parent = current.node.path.slice(0, current.node.path.length - current.node.name.length);
        await renamePath(current.node.path, `${parent}${targetName(name)}`);
        refresh();
      }
      return null;
    } catch (error) {
      return String(error);
    }
  }

  /** git 状态按项目内相对路径索引。 */
  function badgeRel(node: FileNode): string {
    const root = projectPath;
    return root ? absToRel(root, node.path) : node.rel;
  }

  /**
   * 右侧预览是否显示。
   *
   * 判据: 选中了、但它**不是**当前活动的资源/配置选项卡、而且也不是"正在打开"的那一个。
   * 于是三种情况自然都没有预览:
   *   * 目录变更 -> `onDirectoryChange` 清掉选中;
   *   * 再点一次同一项 -> 选中被取消 (见 `selectResource`);
   *   * 双击已打开的资源 -> 它已经成为活动选项卡, 预览与编辑器内容重复, 收起来。
   */
  const previewVisible = $derived(
    Boolean(previewNode) && previewNode?.path !== selectedPath && previewNode?.path !== openingPath
  );

  /** 右侧预览的媒体地址 (走预览站点, 不读字节)。 */
  const previewUrl = $derived(previewVisible && previewNode && assetBase ? assetUrl(previewNode.rel) : undefined);
  /** 文本资源要读磁盘才能预览 */
  let previewText = $state<string | null>(null);
  let previewTextPath: string | null = null;

  $effect(() => {
    const node = previewVisible ? previewNode : null;
    if (!node || (node.kind !== 'text' && node.kind !== 'scene' && node.kind !== 'other')) {
      previewText = null;
      previewTextPath = null;
      return;
    }
    // 已经读过同一个文件就不重复读
    if (previewTextPath === node.path) return;
    let cancelled = false;
    void (async () => {
      try {
        const text = await fs.readTextLossy(node.path);
        if (cancelled) return;
        previewText = text.length > 4000 ? `${text.slice(0, 4000)}\n\n…（已截断）` : text;
        previewTextPath = node.path;
      } catch {
        if (!cancelled) previewText = '（读不到这个文件的内容）';
      }
    })();
    return () => {
      cancelled = true;
    };
  });
</script>

{#snippet rowBadge(node: FileNode)}
  <!--
    值在父级算好再传进去 (见 `gitLetters` / `diagCounts` 的说明): 每行只做两次 O(1) 查表,
    订阅只发生在父级这一处。
  -->
  {@const rel = badgeRel(node)}
  {@const counts = diagCounts.get(node.path)}
  <FileBadges
    path={node.path}
    {rel}
    letter={gitLetters.get(normalizeRelPath(rel)) ?? null}
    errors={counts?.errors ?? 0}
    warnings={counts?.warnings ?? 0}
  />
{/snippet}

{#snippet previewPane()}
  <div class="resource-preview">
    {#if !previewNode}
      <p class="muted">单击左侧的文件即可在这里预览；双击打开为选项卡。</p>
    {:else if previewNode.kind === 'image'}
      {#if previewUrl}
        <img src={previewUrl} alt={previewNode.name} />
      {:else}
        <p class="muted">预览站点还没就绪。</p>
      {/if}
    {:else if previewNode.kind === 'video'}
      {#if previewUrl}
        <!-- 素材预览: 没有字幕轨可言, 这是本地资源查看器而不是播放器界面 -->
        <!-- svelte-ignore a11y_media_has_caption -->
        <video src={previewUrl} controls></video>
      {:else}
        <p class="muted">预览站点还没就绪。</p>
      {/if}
    {:else if previewNode.kind === 'audio'}
      {#if previewUrl}
        <audio src={previewUrl} controls></audio>
      {:else}
        <p class="muted">预览站点还没就绪。</p>
      {/if}
    {:else if previewText !== null}
      <pre>{previewText}</pre>
    {:else}
      <p class="muted">正在读取…</p>
    {/if}
    <p class="resource-preview-name muted" title={previewNode?.rel ?? ''}>{previewNode?.rel ?? ''}</p>
  </div>
{/snippet}

<!--
  右侧预览栏作为 FileTree 的 `side` 传入, **由 FileTree 自己摆到列表右边**。

  列表主体必须归 FileTree: 若改成父级用 snippet 把工具栏 + 列表一起包起来, 本组件任何一次
  重渲染都会重建整个列表, 每行的缩略图都要重新请求与解码。
-->
{#snippet previewSide()}
  {#if previewVisible}
    {@render previewPane()}
  {/if}
{/snippet}

{#snippet listFiles()}
  <FileTree
    rootPath={gameRoot}
    {viewStateCache}
    {viewStateKey}
    {refreshKey}
    selectedPath={previewNode?.path ?? selectedPath}
    {revealRequest}
    {onRevealComplete}
    {assetUrl}
    excludeTop={isSceneDirectory}
    menu={toolbarMenu}
    badge={rowBadge}
    side={previewSide}
    onOpen={(node) => selectResource(node)}
    onDoubleClick={(node) => void openResource(node)}
    onBlankContextMenu={(dir, event) => (blankMenu = { x: event.clientX, y: event.clientY, dir })}
    onItemContextMenu={(node, event) => (itemMenu = { x: event.clientX, y: event.clientY, node })}
    onDirectoryChange={() => clearPreview()}
    onDropFiles={(dir, event) => void handleDropFiles(dir, event)}
  />
{/snippet}

{#if projectPath && gameRoot}
  <div class="resource-browser">
    <!-- 不预览时**不渲染**那一栏 (而不是渲染出来再靠 CSS 收起来) -->
    <div class="resource-body" class:no-preview={!previewVisible}>
      {@render listFiles()}
    </div>
  </div>

  {#if blankMenu}
    <ContextMenu x={blankMenu.x} y={blankMenu.y} items={blankItems} onClose={() => (blankMenu = null)} />
  {/if}

  {#if itemMenu}
    <ContextMenu x={itemMenu.x} y={itemMenu.y} items={itemItems} onClose={() => (itemMenu = null)} />
  {/if}

  {#if prompt}
    <NameInputDialog
      title={promptTitle}
      label="名称"
      initialValue={promptInitial}
      selectStem={prompt.mode === 'rename'}
      hint={prompt.mode === 'file' ? '缺扩展名时自动补 .txt' : undefined}
      validate={validateTarget}
      onClose={() => (prompt = null)}
      onSubmit={submitPrompt}
    />
  {/if}
{/if}
